96	## `MessageSubmitted` — lazy session creation + optimistic placeholders + `emit.forEach`
97	
98	```dart
99	Future<void> _onMessageSubmitted(MessageSubmitted event, Emitter<ChatState> emit) async {
100	  final current = state;
101	  if (current is! ChatReady || !current.canSend) return;   // composer was disabled; defensive no-op
102	
103	  if (!await _connectivityChecker.hasConnection()) {        // FR-012 — blocked client-side, never attempted
104	    return;   // composer's own isOffline flag (R8's live stream) will reflect this on its own shortly
105	  }
106	
107	  final generation = ++_turnGeneration;
108	  final now = DateTime.now();
109	  final optimisticUser = ChatMessage(
110	    id: 'local-${now.microsecondsSinceEpoch}', sessionId: current.sessionId ?? '',
111	    role: ChatRole.user, content: event.text, seq: current.messages.length,
112	    status: ChatMessageStatus.complete, retryCount: 0, createdAt: now,
113	  );
114	  final optimisticAssistant = ChatMessage(
115	    id: 'local-${now.microsecondsSinceEpoch}-response', sessionId: current.sessionId ?? '',
116	    role: ChatRole.assistant, content: '', seq: current.messages.length + 1,
117	    status: ChatMessageStatus.streaming, retryCount: 0, createdAt: now,
118	  );
119	  emit(current.copyWith(
120	    messages: [...current.messages, optimisticUser, optimisticAssistant],
121	    awaitingResponse: true,
122	  ));
123	
124	  String sessionId;
125	  if (current.sessionId == null) {
126	    final created = await _chatRepository.createSession(title: ChatTitleDeriver.derive(event.text));
127	    final maybeId = created.match((f) => null, (s) => s.id);
128	    if (maybeId == null) {
129	      if (generation != _turnGeneration) return;
130	      _failTurn(emit, created.getLeft().toNullable()!, optimisticUserId: optimisticUser.id, optimisticAssistantId: optimisticAssistant.id);
131	      return;
132	    }
133	    sessionId = maybeId;
134	    await _chatRepository.setLastActiveSessionId(sessionId);
135	  } else {
136	    sessionId = current.sessionId!;
137	  }
138	
139	  final stream = _chatRepository.sendMessage(sessionId: sessionId, content: event.text);
140	  await _consumeTurn(
141	    stream, emit, generation: generation, sessionId: sessionId,
142	    optimisticUserId: optimisticUser.id, optimisticAssistantId: optimisticAssistant.id,
143	  );
144	}
145	```
