7	```dart
8	class ChatSessionsBloc extends Bloc<ChatSessionsEvent, ChatSessionsState> {
9	  ChatSessionsBloc({required ChatRepository chatRepository})
10	      : _chatRepository = chatRepository, // ignore: prefer_initializing_formals
11	        super(const ChatSessionsLoading()) {
12	    on<SessionsStarted>(_onStarted);
13	    on<SessionsRefreshRequested>(_onRefreshRequested);
14	    on<SessionsNextPageRequested>(_onNextPageRequested);
15	    on<SessionsPageLoadRetried>(_onPageLoadRetried);
16	  }
17	
18	  final ChatRepository _chatRepository;
19	  final _reauthController = StreamController<void>.broadcast();
20	  int _fetchGeneration = 0;
21	
22	  Stream<void> get reauthRequired => _reauthController.stream;
23	}
