60	## `SessionsNextPageRequested` (FR-008)
61	
62	```dart
63	Future<void> _onNextPageRequested(SessionsNextPageRequested event, Emitter<ChatSessionsState> emit) async {
64	  final current = state;
65	  if (current is! ChatSessionsLoaded || current.hasReachedEnd || current.isLoadingMore) return;
66	
67	  final generation = ++_fetchGeneration;
68	  emit(current.copyWith(isLoadingMore: true, pageLoadFailure: null));
69	  final result = await _chatRepository.listSessions(cursor: current.nextCursor);
70	  if (generation != _fetchGeneration) return;
71	
72	  result.match(
73	    (failure) {
74	      if (failure is AuthExpiredFailure) {
75	        _reauthController.add(null);
76	        emit(current.copyWith(isLoadingMore: false));
77	      } else {
78	        emit(current.copyWith(isLoadingMore: false, pageLoadFailure: failure));
79	      }
80	    },
81	    (page) => emit(current.copyWith(
82	      sessions: [...current.sessions, ...page.sessions],
83	      nextCursor: page.nextCursor, isLoadingMore: false, pageLoadFailure: null,
84	    )),
85	  );
86	}
87	```
