89	## `SessionsPageLoadRetried`
90	
91	```dart
92	Future<void> _onPageLoadRetried(SessionsPageLoadRetried event, Emitter<ChatSessionsState> emit) async {
93	  final current = state;
94	  if (current is ChatSessionsLoadFailure) {
95	    await _loadFirstPage(emit);
96	  } else if (current is ChatSessionsLoaded && current.pageLoadFailure != null) {
97	    add(const SessionsNextPageRequested());
98	  }
