37	        .sseStream('chat-messages-send', method: 'POST', pathSegments: [sessionId], body: {'content': content})
38	        .map(_mapFrame)
39	        .where((e) => e != null)
40	        .cast<Either<Failure, ChatStreamEvent>>();
