56	  /// `null` for a frame this app ignores outright (`context` — research.md R2); every other
57	  /// frame maps 1:1 to a `ChatStreamEvent` or, for the backend-named `error` event, to `Left`.
58	  Either<Failure, ChatStreamEvent>? _mapFrame(Either<Failure, SseFrame> frameResult) {
59	    return frameResult.match(
60	      (failure) => Left(failure),   // a transport-level failure from sseStream() itself — passed through as-is
61	      (frame) {
62	        final decoded = jsonDecode(frame.data) as Map<String, dynamic>;
63	        return switch (frame.event) {
64	          'message_created' => Right(MessageCreated(
65	              userMessageId: decoded['userMessageId'] as String,
66	              assistantMessageId: decoded['assistantMessageId'] as String,
67	            )),
68	          'context' => null,
69	          'token' => Right(TokenReceived(decoded['delta'] as String)),
70	          'done' => Right(StreamDone(
71	              assistantMessageId: decoded['assistantMessageId'] as String,
72	              content: decoded['content'] as String,
73	              createdAt: DateTime.parse(decoded['createdAt'] as String),
74	            )),
75	          'error' => Left(ErrorMapper.fromResponse(decoded)),   // business-level failure (research.md R2)
76	          _ => null,   // forward-compatible: an unrecognized event name is ignored, never thrown (FR-003-style "never an unhandled crash")
77	        };
78	      },
79	    );
80	  }
