174	
175	  /// research.md R3 — retries the whole call once only if the *first* item is AuthExpiredFailure.
176	  Stream<Either<Failure, ChatStreamEvent>> _streamWithAuthRetry(
177	    Stream<Either<Failure, ChatStreamEvent>> Function() call,
178	  ) async* {
179	    var isFirst = true;
180	    var retried = false;
181	    var stream = call();
182	    while (true) {
183	      await for (final item in stream) {
184	        if (isFirst && !retried && item.isLeft() &&
185	            item.match((f) => f is AuthExpiredFailure, (_) => false)) {
186	          final refreshed = await _sessionRepository.refresh();
187	          if (refreshed.isLeft()) {
188	            yield item;   // refresh itself failed — surface the original AuthExpiredFailure
189	            return;
190	          }
191	          retried = true;
192	          stream = call();
193	          break;   // restart the outer while(true) with the fresh stream
194	        }
195	        isFirst = false;
196	        yield item;
197	      }
198	      if (!retried || isFirst == false) return;
199	    }
200	  }
201	
202	  void _upsertSession(ChatSession session) {
203	    final i = _cachedSessions.indexWhere((s) => s.id == session.id);
204	    if (i >= 0) {
205	      _cachedSessions[i] = session;
206	    } else {
207	      _cachedSessions = [..._cachedSessions, session];
208	    }
209	  }
210	
211	  Future<Either<Failure, T>> _retryAfterSilentRefreshIfExpired<T>(
212	    Future<Either<Failure, T>> Function() call,
213	  ) async {
214	    final result = await call();
215	    return result.match(
216	      (f) => f is AuthExpiredFailure ? _retryAfterSilentRefresh(call) : Future.value(Left(f)),
217	      (v) => Future.value(Right(v)),
218	    );
219	  }
220	
221	  // _retryAfterSilentRefresh: identical to EntriesRepositoryImpl's own (exactly one retry, no loop).
222	}
223	```
