336	  /// Shared `emit.forEach`-driven stream consumption for both a fresh send
337	  /// and a retry.
338	  Future<void> _consumeTurn(
339	    Stream<Either<Failure, ChatStreamEvent>> stream,
340	    Emitter<ChatState> emit, {
341	    required int generation,
342	    required String? optimisticUserId,
343	    required String optimisticAssistantId,
344	  }) async {
345	    var assistantId = optimisticAssistantId;
346	    await emit.forEach<Either<Failure, ChatStreamEvent>>(
347	      stream,
348	      onData: (result) {
349	        final latest = state;
350	        if (generation != _turnGeneration || latest is! ChatReady) {
351	          return latest;
352	        }
353	        return result.match((failure) {
354	          if (failure is AuthExpiredFailure) _reauthController.add(null);
355	          return _applyFailure(latest, assistantId, failure);
356	        }, (event) => switch (event) {
357	          MessageCreated() => () {
358	            assistantId = event.assistantMessageId;
359	            return _reconcileIds(
360	              latest,
361	              optimisticUserId,
362	              event.userMessageId,
363	              optimisticAssistantId,
364	              event.assistantMessageId,
365	            );
366	          }(),
367	          ContextReceived() => latest,
368	          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
369	          StreamDone(
370	            assistantMessageId: final id,
371	            content: final c,
372	            createdAt: final t,
373	          ) =>
374	            _completeMessage(latest, id, c, t).copyWith(awaitingResponse: false),
375	        });
376	      },
377	    );
378	  }
