1	import 'dart:async';
2	
3	import 'package:cerne/core/network/failure.dart';
4	import 'package:cerne/features/chat/domain/repositories/chat_repository.dart';
5	import 'package:cerne/features/chat/presentation/bloc/chat_sessions_event.dart';
6	import 'package:cerne/features/chat/presentation/bloc/chat_sessions_state.dart';
7	import 'package:flutter_bloc/flutter_bloc.dart';
8	
9	/// The side menu's "CONVERSAS" list — paginated, offline-cached, directly
10	/// mirroring `RecordsBloc`'s own first-page/next-page/retry shape (RF07).
11	/// Depends only on `ChatRepository` — never `ChatBloc`, `SessionBloc`, or
12	/// `ConnectivityChecker` (research.md R7).
13	class ChatSessionsBloc extends Bloc<ChatSessionsEvent, ChatSessionsState> {
14	  ChatSessionsBloc({required ChatRepository chatRepository})
15	    : _chatRepository = chatRepository, // ignore: prefer_initializing_formals
16	      super(const ChatSessionsLoading()) {
17	    on<SessionsStarted>(_onStarted);
18	    on<SessionsRefreshRequested>(_onRefreshRequested);
19	    on<SessionsNextPageRequested>(_onNextPageRequested);
20	    on<SessionsPageLoadRetried>(_onPageLoadRetried);
21	  }
22	
23	  final ChatRepository _chatRepository;
24	  final _reauthController = StreamController<void>.broadcast();
25	  int _fetchGeneration = 0;
26	
27	  Stream<void> get reauthRequired => _reauthController.stream;
28	
29	  Future<void> _onStarted(
30	    SessionsStarted event,
31	    Emitter<ChatSessionsState> emit,
32	  ) async {
33	    emit(const ChatSessionsLoading());
34	    await _loadFirstPage(emit);
35	  }
36	
37	  Future<void> _onRefreshRequested(
38	    SessionsRefreshRequested event,
39	    Emitter<ChatSessionsState> emit,
40	  ) async {
41	    // Unlike _onStarted, never regresses a populated ChatSessionsLoaded back
42	    // to ChatSessionsLoading — the drawer's existing list stays visible
43	    // while a fresh page 1 loads underneath it.
44	    await _loadFirstPage(emit);
45	  }
46	
47	  Future<void> _loadFirstPage(Emitter<ChatSessionsState> emit) async {
48	    final generation = ++_fetchGeneration;
49	    final result = await _chatRepository.listSessions();
50	    if (generation != _fetchGeneration) return;
51	
52	    result.match(
53	      (failure) {
54	        final cached = _chatRepository.cachedSessions;
55	        if (failure is AuthExpiredFailure) _reauthController.add(null);
56	        if (cached.isEmpty) {
57	          emit(ChatSessionsLoadFailure(failure));
58	        } else {
59	          emit(
60	            ChatSessionsLoaded(sessions: cached, nextCursor: null, isLoadingMore: false),
61	          );
62	        }
63	      },
64	      (page) => emit(
65	        ChatSessionsLoaded(
66	          sessions: page.sessions,
67	          nextCursor: page.nextCursor,
68	          isLoadingMore: false,
69	        ),
70	      ),
71	    );
72	  }
73	
74	  Future<void> _onNextPageRequested(
75	    SessionsNextPageRequested event,
76	    Emitter<ChatSessionsState> emit,
77	  ) async {
78	    final current = state;
79	    if (current is! ChatSessionsLoaded || current.hasReachedEnd || current.isLoadingMore) {
80	      return;
81	    }
82	
83	    final generation = ++_fetchGeneration;
84	    emit(current.copyWith(isLoadingMore: true, pageLoadFailure: null));
85	    final result = await _chatRepository.listSessions(cursor: current.nextCursor);
86	    if (generation != _fetchGeneration) return;
87	
88	    result.match(
89	      (failure) {
90	        if (failure is AuthExpiredFailure) {
91	          _reauthController.add(null);
92	          emit(current.copyWith(isLoadingMore: false, pageLoadFailure: null));
93	        } else {
94	          emit(current.copyWith(isLoadingMore: false, pageLoadFailure: failure));
95	        }
96	      },
97	      (page) => emit(
98	        current.copyWith(
99	          sessions: [...current.sessions, ...page.sessions],
100	          nextCursor: page.nextCursor,
101	          isLoadingMore: false,
102	          pageLoadFailure: null,
103	        ),
104	      ),
105	    );
106	  }
107	
108	  Future<void> _onPageLoadRetried(
109	    SessionsPageLoadRetried event,
110	    Emitter<ChatSessionsState> emit,
111	  ) async {
112	    final current = state;
113	    if (current is ChatSessionsLoadFailure) {
114	      await _loadFirstPage(emit);
115	    } else if (current is ChatSessionsLoaded && current.pageLoadFailure != null) {
116	      add(const SessionsNextPageRequested());
117	    }
118	  }
119	
120	  @override
121	  Future<void> close() {
122	    unawaited(_reauthController.close());
123	    return super.close();
124	  }
125	}
