3	import 'package:cerne/core/network/failure.dart';
4	import 'package:cerne/features/chat/data/chat_local_cache.dart';
5	import 'package:cerne/features/chat/data/chat_remote_data_source.dart';
6	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
7	import 'package:cerne/features/chat/domain/entities/chat_session.dart';
8	import 'package:cerne/features/chat/domain/entities/chat_sessions_page.dart';
9	import 'package:cerne/features/chat/domain/entities/chat_stream_event.dart';
10	import 'package:cerne/features/chat/domain/repositories/chat_repository.dart';
11	import 'package:cerne/features/session/domain/repositories/session_repository.dart';
12	import 'package:fpdart/fpdart.dart';
13	
14	/// Wraps [ChatRemoteDataSource] + [ChatLocalCache] + [SessionRepository]
15	/// (for the silent-refresh retry, research.md R3) — same constructor shape
16	/// as `EntriesRepositoryImpl`. Registered as a `get_it` `lazySingleton` so
17	/// [cachedSessions]/[cachedMessages] survive across screen rebuilds.
18	class ChatRepositoryImpl implements ChatRepository {
19	  ChatRepositoryImpl(
20	    this._remoteDataSource, {
21	    required this._sessionRepository,
22	    required this._localCache,
23	  });
24	
25	  final ChatRemoteDataSource _remoteDataSource;
26	  final SessionRepository _sessionRepository;
27	  final ChatLocalCache _localCache;
28	
29	  List<ChatSession> _cachedSessions = [];
30	  final Map<String, List<ChatMessage>> _cachedMessages = {};
31	  Future<void>? _localCacheLoad;
32	
33	  Future<void> _ensureLocalCacheLoaded() {
34	    return _localCacheLoad ??= () async {
35	      _cachedSessions = await _localCache.readSessions();
36	      _cachedMessages.addAll(await _localCache.readAllMessages());
37	    }();
38	  }
39	
40	  @override
41	  Future<Either<Failure, ChatSession>> createSession({
42	    required String title,
43	  }) async {
44	    await _ensureLocalCacheLoaded();
45	    final result = await _retryAfterSilentRefreshIfExpired(
46	      () => _remoteDataSource.createSession(title: title),
47	    );
48	    return result.match((f) => Left(f), (session) {
49	      _upsertSession(session);
50	      unawaited(_localCache.writeSessions(_cachedSessions));
51	      return Right(session);
52	    });
53	  }
54	
55	  @override
56	  Future<Either<Failure, ChatSessionsPage>> listSessions({
57	    String? cursor,
58	    int? limit,
59	  }) async {
60	    await _ensureLocalCacheLoaded();
61	    final result = await _retryAfterSilentRefreshIfExpired(
62	      () => _remoteDataSource.listSessions(cursor: cursor, limit: limit),
63	    );
64	    return result.match((f) => Left(f), (page) {
65	      for (final s in page.sessions) {
66	        _upsertSession(s);
67	      }
68	      unawaited(_localCache.writeSessions(_cachedSessions));
69	      return Right(page);
70	    });
71	  }
72	
73	  @override
74	  List<ChatSession> get cachedSessions => List.unmodifiable(_cachedSessions);
75	
76	  @override
77	  Future<Either<Failure, List<ChatMessage>>> listMessages(
78	    String sessionId,
79	  ) async {
80	    await _ensureLocalCacheLoaded();
81	    final result = await _retryAfterSilentRefreshIfExpired(
82	      () => _remoteDataSource.listMessages(sessionId),
83	    );
84	    return result.match((f) => Left(f), (messages) {
85	      _cachedMessages[sessionId] = messages;
86	      unawaited(_localCache.writeMessagesForSession(sessionId, messages));
87	      return Right(messages);
88	    });
89	  }
90	
91	  @override
92	  List<ChatMessage>? cachedMessages(String sessionId) =>
93	      _cachedMessages[sessionId];
94	
95	  @override
96	  Future<void> setLastActiveSessionId(String? sessionId) =>
97	      _localCache.writeLastActiveSessionId(sessionId);
98	
99	  @override
100	  Future<String?> get lastActiveSessionId =>
101	      _localCache.readLastActiveSessionId();
102	
103	  @override
104	  Stream<Either<Failure, ChatStreamEvent>> sendMessage({
105	    required String sessionId,
106	    required String content,
107	  }) => _streamWithAuthRetry(
108	    () => _remoteDataSource.sendMessage(sessionId: sessionId, content: content),
109	  );
110	
111	  @override
112	  Stream<Either<Failure, ChatStreamEvent>> retryMessage({
113	    required String sessionId,
114	    required String userMessageId,
115	  }) => _streamWithAuthRetry(
116	    () => _remoteDataSource.retryMessage(
117	      sessionId: sessionId,
118	      userMessageId: userMessageId,
119	    ),
120	  );
121	
122	  /// research.md R3 — retries the whole call once, only if the *first* item
123	  /// is `AuthExpiredFailure` (i.e. before any `ChatStreamEvent` was ever
124	  /// emitted). Once any event has been emitted, a later `AuthExpiredFailure`
125	  /// is yielded as-is, no retry attempted.
126	  Stream<Either<Failure, ChatStreamEvent>> _streamWithAuthRetry(
127	    Stream<Either<Failure, ChatStreamEvent>> Function() call,
128	  ) async* {
129	    var stream = call();
130	    var canRetry = true;
131	    while (true) {
132	      var sawAnyItem = false;
133	      var restarted = false;
134	      await for (final item in stream) {
135	        if (!sawAnyItem &&
136	            canRetry &&
137	            item.match((f) => f is AuthExpiredFailure, (_) => false)) {
138	          final refreshed = await _sessionRepository.refresh();
139	          if (refreshed.isLeft()) {
140	            yield item;
141	            return;
142	          }
143	          canRetry = false;
144	          stream = call();
145	          restarted = true;
146	          break;
147	        }
148	        sawAnyItem = true;
149	        yield item;
150	      }
151	      if (!restarted) return;
152	    }
153	  }
154	
155	  /// Keeps `_cachedSessions` ordered by `lastUserMessageAt` descending
156	  /// (nulls last) after every mutation — the order `cachedSessions`'
157	  /// offline fallback (`ChatSessionsBloc._loadFirstPage`) relies on, since
158	  /// the online path renders the backend's own already-ordered page instead
159	  /// (FR-008).
160	  void _upsertSession(ChatSession session) {
161	    final i = _cachedSessions.indexWhere((s) => s.id == session.id);
162	    if (i >= 0) {
163	      _cachedSessions[i] = session;
164	    } else {
165	      _cachedSessions = [..._cachedSessions, session];
166	    }
167	    _cachedSessions.sort((a, b) {
168	      final aTime = a.lastUserMessageAt;
169	      final bTime = b.lastUserMessageAt;
170	      if (aTime == null && bTime == null) return 0;
171	      if (aTime == null) return 1;
172	      if (bTime == null) return -1;
173	      return bTime.compareTo(aTime);
174	    });
175	  }
176	
177	  // Exactly one retry. If it also comes back `AuthExpiredFailure` (a
178	  // pathological double-expiry), that is returned as-is — no second refresh
179	  // attempt, no loop (same shape EntriesRepositoryImpl already uses).
180	  Future<Either<Failure, T>> _retryAfterSilentRefreshIfExpired<T>(
181	    Future<Either<Failure, T>> Function() call,
182	  ) async {
183	    final result = await call();
184	    return result.match(
185	      (f) => f is AuthExpiredFailure
186	          ? _retryAfterSilentRefresh(call)
187	          : Future.value(Left(f)),
188	      (v) => Future.value(Right(v)),
189	    );
190	  }
191	
192	  Future<Either<Failure, T>> _retryAfterSilentRefresh<T>(
193	    Future<Either<Failure, T>> Function() retry,
194	  ) async {
195	    final refreshed = await _sessionRepository.refresh();
196	    return refreshed.match(
197	      (_) => Future.value(
198	        const Left(
199	          AuthExpiredFailure(
200	            message: 'Session could not be renewed',
201	            requestId: '',
202	          ),
203	        ),
204	      ),
205	      (_) => retry(),
206	    );
207	  }
208	}
