3	import 'package:equatable/equatable.dart';
4	
5	sealed class ChatState extends Equatable {
6	  const ChatState();
7	
8	  @override
9	  List<Object?> get props => [];
10	}
11	
12	/// Only while resuming `lastActiveSessionId` on `ChatStarted`.
13	class ChatLoading extends ChatState {
14	  const ChatLoading();
15	}
16	
17	/// Everything else — an existing conversation, the empty "Novo Chat" state,
18	/// or an outright load failure with nothing cached to fall back to — are all
19	/// one state shape so the screen never has to discard/rebuild its
20	/// `Scaffold`/`AppBar` switching between them.
21	class ChatReady extends ChatState {
22	  const ChatReady({
23	    required this.sessionId,
24	    required this.messages,
25	    required this.isOffline,
26	    required this.awaitingResponse,
27	    this.loadFailure,
28	  });
29	
30	  /// `null` = empty conversation, no session created yet (FR-010).
31	  final String? sessionId;
32	
33	  /// `[]` for an empty conversation.
34	  final List<ChatMessage> messages;
35	  final bool isOffline;
36	
37	  /// research.md R9 — gates the composer, true during a send/retry turn.
38	  final bool awaitingResponse;
