1	/// Derives a side-menu preview title from a conversation's first message
2	/// (FR-010, research.md R6). Pure, total; no `package:flutter` import, no
3	/// I/O (Principle V).
4	class ChatTitleDeriver {
5	  const ChatTitleDeriver._();
6	
7	  static const _maxLength = 48;
8	
9	  /// Collapses internal whitespace/newlines to single spaces, trims, and
10	  /// caps the result at 48 characters (appending `'…'` when truncated).
11	  /// Never returns an empty string for non-empty input.
12	  static String derive(String firstMessageText) {
