1	import 'dart:convert';
2	
3	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
4	import 'package:cerne/features/chat/domain/entities/chat_session.dart';
5	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
6	
7	/// On-device, cross-restart persistence for chat (research.md R4) —
8	/// Keychain-backed, same pattern `EntriesLocalCache` already establishes.
9	/// Three **independent** storage keys so one write never clobbers another.
10	class ChatLocalCache {
11	  ChatLocalCache({FlutterSecureStorage? storage})
12	    : _storage = storage ?? const FlutterSecureStorage();
13	
14	  final FlutterSecureStorage _storage;
15	
16	  static const _sessionsKey = 'chatSessionsLocalCache';
17	  static const _messagesKey = 'chatMessagesLocalCache';
18	  static const _lastActiveKey = 'chatLastActiveSessionId';
19	
20	  Future<List<ChatSession>> readSessions() async {
21	    final raw = await _storage.read(key: _sessionsKey);
22	    if (raw == null) return const [];
23	    try {
24	      final decoded = jsonDecode(raw) as List<dynamic>;
25	      return decoded
26	          .map((e) => _sessionFromJson(e as Map<String, dynamic>))
27	          .toList();
28	    } on FormatException {
29	      return const [];
30	    } on TypeError {
31	      return const [];
32	    }
33	  }
34	
35	  Future<void> writeSessions(List<ChatSession> sessions) {
36	    final encoded = jsonEncode(sessions.map(_sessionToJson).toList());
37	    return _storage.write(key: _sessionsKey, value: encoded);
38	  }
39	
40	  Future<Map<String, List<ChatMessage>>> readAllMessages() async {
41	    final raw = await _storage.read(key: _messagesKey);
42	    if (raw == null) return const {};
43	    try {
44	      final decoded = jsonDecode(raw) as Map<String, dynamic>;
45	      return decoded.map(
46	        (sessionId, messages) => MapEntry(
47	          sessionId,
48	          (messages as List<dynamic>)
49	              .map((m) => _messageFromJson(m as Map<String, dynamic>))
50	              .toList(),
51	        ),
52	      );
53	    } on FormatException {
54	      return const {};
55	    } on TypeError {
56	      return const {};
57	    }
58	  }
59	
60	  Future<void> writeMessagesForSession(
61	    String sessionId,
62	    List<ChatMessage> messages,
63	  ) async {
64	    final all = await readAllMessages();
65	    final updated = {...all, sessionId: messages};
66	    final encoded = jsonEncode(
67	      updated.map(
68	        (sid, msgs) => MapEntry(sid, msgs.map(_messageToJson).toList()),
69	      ),
70	    );
71	    await _storage.write(key: _messagesKey, value: encoded);
72	  }
73	
74	  Future<String?> readLastActiveSessionId() {
75	    return _storage.read(key: _lastActiveKey);
76	  }
77	
78	  Future<void> writeLastActiveSessionId(String? sessionId) {
79	    if (sessionId == null) {
80	      return _storage.delete(key: _lastActiveKey);
81	    }
82	    return _storage.write(key: _lastActiveKey, value: sessionId);
83	  }
84	
85	  Map<String, dynamic> _sessionToJson(ChatSession s) => {
86	    'id': s.id,
87	    'title': s.title,
88	    'personaSnapshot': s.personaSnapshot.name,
89	    'userMessageCount': s.userMessageCount,
90	    'lastUserMessageAt': s.lastUserMessageAt?.toUtc().toIso8601String(),
91	    'createdAt': s.createdAt.toUtc().toIso8601String(),
92	    'updatedAt': s.updatedAt.toUtc().toIso8601String(),
93	  };
94	
95	  ChatSession _sessionFromJson(Map<String, dynamic> data) => ChatSession(
96	    id: data['id'] as String,
97	    title: data['title'] as String,
98	    personaSnapshot: ChatPersona.values.byName(
99	      data['personaSnapshot'] as String,
100	    ),
101	    userMessageCount: data['userMessageCount'] as int,
102	    lastUserMessageAt: (data['lastUserMessageAt'] as String?) == null
103	        ? null
104	        : DateTime.parse(data['lastUserMessageAt'] as String),
105	    createdAt: DateTime.parse(data['createdAt'] as String),
106	    updatedAt: DateTime.parse(data['updatedAt'] as String),
107	  );
108	
109	  Map<String, dynamic> _messageToJson(ChatMessage m) => {
110	    'id': m.id,
111	    'sessionId': m.sessionId,
112	    'role': m.role.name,
113	    'content': m.content,
114	    'seq': m.seq,
115	    'status': m.status.name,
116	    'retryCount': m.retryCount,
117	    'createdAt': m.createdAt.toUtc().toIso8601String(),
118	  };
119	
120	  ChatMessage _messageFromJson(Map<String, dynamic> data) => ChatMessage(
121	    id: data['id'] as String,
122	    sessionId: data['sessionId'] as String,
123	    role: ChatRole.values.byName(data['role'] as String),
124	    content: data['content'] as String,
125	    seq: data['seq'] as int,
126	    status: ChatMessageStatus.values.byName(data['status'] as String),
127	    retryCount: data['retryCount'] as int,
128	    createdAt: DateTime.parse(data['createdAt'] as String),
129	  );
130	}
