3	/// Interface-level online/offline check (research.md R5) — lives in `core/`,
4	/// not inside `capture/`, because later offline-gated units (RF04, RF06)
5	/// reuse this exact checker. Reports OS-level interface state (Wi-Fi/
6	/// cellular/none), not actual internet reachability — an accepted
7	/// limitation (research.md R5).
8	class ConnectivityChecker {
9	  ConnectivityChecker({Connectivity? connectivity})
10	    : _connectivity = connectivity ?? Connectivity();
11	
12	  final Connectivity _connectivity;
13	
14	  Future<bool> hasConnection() async {
15	    final results = await _connectivity.checkConnectivity();
16	    return results.any((result) => result != ConnectivityResult.none);
17	  }
18	
19	  /// Live connectivity transitions (research.md R8) — layered on top of,
20	  /// never replacing, [hasConnection]'s own synchronous pre-check. Maps "any
21	  /// result `!= ConnectivityResult.none`" to `true`, the exact predicate
22	  /// [hasConnection] already uses.
23	  Stream<bool> get onConnectivityChanged => _connectivity.onConnectivityChanged
24	      .map((results) => results.any((result) => result != ConnectivityResult.none));
25	}
