31	  Future<Either<Failure, Map<String, dynamic>>> call(
32	    String function, {
33	    required String method,
34	    Map<String, dynamic>? body,
35	    List<String>? pathSegments,
36	    Map<String, dynamic>? queryParameters,
37	    AuthMode authMode = AuthMode.userSession,
