40	    // object. Needed by `entries-list`, whose "data" is an array (not an
41	    // object) and whose "meta.nextCursor" every other call site has no use
42	    // for and would otherwise be discarded. Every pre-existing call site
43	    // omits this and is byte-for-byte unaffected.
44	    bool unwrapData = true,
45	  }) async {
46	    final baseUrl = dotenv.env['FUNCTIONS_BASE_URL'] ?? '';
47	    final segments = [function, ...?pathSegments];
48	    final url = '$baseUrl/${segments.join('/')}';
49	
50	    final bearer = authMode == AuthMode.anonKey
51	        ? _anonKey
52	        : (await _tokenStorage.readAccessToken() ?? '');
53	
54	    try {
55	      final response = await _dio.request<Map<String, dynamic>>(
56	        url,
57	        data: body,
58	        queryParameters: queryParameters,
59	        options: Options(
60	          method: method,
61	          headers: {'apikey': _anonKey, 'Authorization': 'Bearer $bearer'},
62	        ),
63	      );
64	      if (!unwrapData) {
65	        return Right(response.data ?? const {});
66	      }
67	      final rawData = response.data?['data'];
68	      if (rawData != null && rawData is! Map<String, dynamic>) {
