82	  /// Generic SSE transport (research.md R1) — knows nothing about chat
83	  /// specifically; any future SSE-consuming unit reuses it as-is. Never
84	  /// throws past this boundary: a transport failure becomes the stream's one
85	  /// and only `Left(Failure)` item, yielded last, then the stream closes.
86	  Stream<Either<Failure, SseFrame>> sseStream(
87	    String function, {
88	    required String method,
89	    Map<String, dynamic>? body,
90	    List<String>? pathSegments,
91	    AuthMode authMode = AuthMode.userSession,
92	  }) async* {
93	    final baseUrl = dotenv.env['FUNCTIONS_BASE_URL'] ?? '';
94	    final segments = [function, ...?pathSegments];
95	    final url = '$baseUrl/${segments.join('/')}';
96	
97	    final bearer = authMode == AuthMode.anonKey
98	        ? _anonKey
99	        : (await _tokenStorage.readAccessToken() ?? '');
100	
101	    try {
102	      final response = await _dio.request<ResponseBody>(
103	        url,
104	        data: body,
105	        options: Options(
106	          method: method,
107	          responseType: ResponseType.stream,
108	          headers: {'apikey': _anonKey, 'Authorization': 'Bearer $bearer'},
109	        ),
110	      );
111	
112	      final buffer = StringBuffer();
113	      await for (final chunk in response.data!.stream) {
114	        buffer.write(utf8.decode(chunk, allowMalformed: true));
115	        var text = buffer.toString();
116	        while (text.contains('\n\n')) {
117	          final splitIndex = text.indexOf('\n\n');
118	          final rawFrame = text.substring(0, splitIndex);
119	          text = text.substring(splitIndex + 2);
120	          final frame = _parseFrame(rawFrame);
121	          if (frame != null) yield Right(frame);
122	        }
123	        buffer
124	          ..clear()
