132	  SseFrame? _parseFrame(String rawFrame) {
133	    String? event;
134	    final dataLines = <String>[];
135	    for (final line in rawFrame.split('\n')) {
136	      if (line.startsWith('event:')) {
137	        event = line.substring(6).trim();
138	      } else if (line.startsWith('data:')) {
139	        dataLines.add(line.substring(5).trim());
140	      }
141	      // Any other SSE field (id:, retry:, comments starting with ':') is
142	      // ignored — this backend's contract never sends them.
143	    }
144	    if (event == null) return null;
145	    return SseFrame(event: event, data: dataLines.join('\n'));
146	  }
