148	  Failure _mapException(DioException e) {
149	    const timeoutTypes = {
150	      DioExceptionType.connectionTimeout,
151	      DioExceptionType.sendTimeout,
152	      DioExceptionType.receiveTimeout,
153	    };
154	
155	    // `e.message` is Dio's own internal exception text (e.g. "Failed host
156	    // lookup") — never shown to the user; both client-synthesized failures
157	    // below carry a fixed, user-facing message instead, same as every
158	    // backend-mapped `Failure` already does via `ErrorMapper`.
159	    if (timeoutTypes.contains(e.type)) {
160	      return const NetworkTimeoutFailure(
161	        message: 'A conexão demorou demais. Tente novamente.',
162	        requestId: '',
163	      );
164	    }
165	
166	    final responseData = e.response?.data;
167	    if (responseData is Map<String, dynamic>) {
168	      return ErrorMapper.fromResponse(responseData);
169	    }
170	
171	    // No response at all (connection error) — NETWORK_OFFLINE never arrives
172	    // as an HTTP response, so it is synthesized client-side here.
173	    return const NetworkOfflineFailure(
174	      message: 'Sem conexão com a internet.',
175	      requestId: '',
176	    );
177	  }
178	}
